#include "fitting/fit_module.hpp"
#include "optimization/opt_module.hpp"
#include "evolution/evolution_module.hpp"
#include "roots/root_module.hpp"
#include <algorithm>
#include <atomic>
#include <cmath>
#include <iostream>
#include <stdexcept>
#include <thread>
#include <vector>
namespace {
int checks=0,failures=0;void expect(bool okay,const char* label){++checks;if(!okay){++failures;std::cerr<<"FAIL: "<<label<<'\n';}}
struct Counter{std::atomic_uint64_t calls{0};};
int residual(void* raw,const double* x,uint64_t n,double* r,uint64_t m,double* j,char*,uint64_t){++static_cast<Counter*>(raw)->calls;for(uint64_t row=0;row<m;++row){r[row]=x[row]-(row==0?2:-1);if(j)for(uint64_t col=0;col<n;++col)j[row*n+col]=row==col?1:0;}return 0;}
int objective(void* raw,const double* x,uint64_t n,double* f,uint64_t,double* j,char*,uint64_t){++static_cast<Counter*>(raw)->calls;f[0]=0;for(uint64_t k=0;k<n;++k){const double v=x[k]-(k==0?2:-1);f[0]+=v*v;if(j)j[k]=2*v;}return 0;}
int evolutionObjective(void* raw,const double* x,uint64_t n,double* f,uint64_t m,char* e,uint64_t c){return objective(raw,x,n,f,m,nullptr,e,c);}
int rootResidual(void* raw,const double* x,uint64_t n,double* r,double* j,char* e,uint64_t c){return residual(raw,x,n,r,n,j,e,c);}
struct Observer{
    uint32_t event;uint64_t stopAfter=0;bool throwOnIter=false;std::thread::id driver=std::this_thread::get_id();std::vector<uint32_t> phases;uint64_t previous=0;bool inspectCost=false;
    explicit Observer(uint32_t kind,uint64_t stop=0):event(kind),stopAfter(stop){}
    bool operator()(const penta_iteration_snapshot_v1& s){expect(std::this_thread::get_id()==driver,"observer runs only on owner driver thread");expect(s.struct_size==sizeof(s)&&s.abi_version==PENTA_ITERATION_ABI_V1&&s.dimension==2&&s.x,"borrowed snapshot layout valid");expect(s.event==event,"backend progress event is honestly labeled");expect(s.evaluations>=previous,"snapshot counts monotone");previous=s.evaluations;phases.push_back(s.phase);for(uint64_t j=0;j<s.dimension;++j)expect(std::isfinite(s.x[j]),"snapshot candidate is finite");if(inspectCost){const double exact=.5*((s.x[0]-2)*(s.x[0]-2)+(s.x[1]+1)*(s.x[1]+1));expect(std::abs(exact-s.objective)<1e-9*(1+exact),"Ceres physical accepted candidate matches reported cost");}if(throwOnIter&&s.phase==PENTA_ITERATION_ITER)throw std::runtime_error("observer regression exception");return stopAfter&&s.phase==PENTA_ITERATION_ITER&&(s.event==PENTA_ITERATION_EVENT_EVALUATION?s.evaluations:s.iteration)>=stopAfter;}
    void validate(){expect(!phases.empty()&&phases.front()==PENTA_ITERATION_INIT&&phases.back()==PENTA_ITERATION_DONE,"observer emits init through done");expect(std::count(phases.begin(),phases.end(),PENTA_ITERATION_INIT)==1&&std::count(phases.begin(),phases.end(),PENTA_ITERATION_DONE)==1,"init and done occur exactly once");}
};
template<class F>void observerException(F call){try{call();expect(false,"observer exception must propagate");}catch(const std::runtime_error& e){expect(std::string(e.what())=="observer regression exception","original observer exception preserved");}}
void fit(){Counter counter;double initial[]{0,0},scale[]{100,.1};penta_fit_request_v1 q{};q.struct_size=sizeof(q);q.method=1;q.dimension=2;q.residual_count=2;q.initial=initial;q.max_iterations=100;q.max_evaluations=1000;q.history_capacity=100;q.threads=2;q.loss_scale=1;q.function_tolerance=q.gradient_tolerance=q.parameter_tolerance=1e-12;q.maximum_wall_seconds=30;q.noise_variance=-1;q.parameter_scale=scale;q.callback_context=&counter;q.evaluate=residual;penta::fitting::Module module;const auto baseline=module.solve(q);const auto baselineCalls=counter.calls.load();counter.calls=0;Observer observer{PENTA_ITERATION_EVENT_ITERATION};observer.inspectCost=true;const auto observed=module.solve(q,{}, {},std::ref(observer));observer.validate();expect(observed.solution==baseline.solution&&counter.calls==baselineCalls,"Ceres progress adds no residual evaluations or numerical changes");
    Observer stop{PENTA_ITERATION_EVENT_ITERATION,1};const auto stopped=module.solve(q,{}, {},std::ref(stop));stop.validate();expect(!stopped.report.converged&&std::string(stopped.report.status)=="output_function_stop","Ceres clean observer stop is not convergence/cancellation");expect(stopped.report.iterations==1,"Ceres stops at requested iteration");
    Observer failure{PENTA_ITERATION_EVENT_ITERATION};failure.throwOnIter=true;observerException([&]{(void)module.solve(q,{}, {},std::ref(failure));});
}
void optimize(){Counter counter;double initial[]{0,0};penta_opt_request_v1 q{};q.struct_size=sizeof(q);q.algorithm=1;q.dimension=2;q.initial=initial;q.max_evaluations=1000;q.history_capacity=100;q.ftol_relative=q.ftol_absolute=q.xtol_relative=q.xtol_absolute=1e-12;q.maximum_wall_seconds=30;q.constraint_tolerance=1e-8;q.objective_context=&counter;q.objective=objective;penta::optimization::Module module;const auto baseline=module.solve(q);const auto calls=counter.calls.load();counter.calls=0;Observer observer{PENTA_ITERATION_EVENT_EVALUATION};const auto observed=module.solve(q,{}, {},std::ref(observer));observer.validate();expect(baseline.solution==observed.solution&&counter.calls==calls,"NLopt progress adds no evaluations or numerical changes");Observer stop{PENTA_ITERATION_EVENT_EVALUATION,2};const auto stopped=module.solve(q,{}, {},std::ref(stop));stop.validate();expect(stopped.report.evaluations==2&&!stopped.report.converged&&std::string(stopped.report.status)=="output_function_stop","NLopt supports clean evaluation-stream stop");Observer failure{PENTA_ITERATION_EVENT_EVALUATION};failure.throwOnIter=true;observerException([&]{(void)module.solve(q,{}, {},std::ref(failure));});}
void evolve(){Counter counter;double initial[]{0,0},lower[]{-3,-3},upper[]{3,3};penta_evolution_request_v1 q{};q.struct_size=sizeof(q);q.algorithm=3;q.seed=42;q.population=40;q.dimension=2;q.objectives=1;q.initial=initial;q.lower=lower;q.upper=upper;q.max_generations=20;q.max_evaluations=1000;q.history_capacity=30;q.maximum_wall_seconds=30;q.ftol=q.xtol=0;q.callback_context=&counter;q.evaluate=evolutionObjective;penta::evolution::Module module;const auto baseline=module.solve(q,4);const auto calls=counter.calls.load();counter.calls=0;Observer observer{PENTA_ITERATION_EVENT_GENERATION};const auto observed=module.solve(q,4,{}, {},std::ref(observer));observer.validate();expect(baseline.solution==observed.solution&&baseline.populationX==observed.populationX&&counter.calls==calls,"CMA progress adds no evaluations or candidate changes");Observer stop{PENTA_ITERATION_EVENT_GENERATION,2};const auto stopped=module.solve(q,4,{}, {},std::ref(stop));stop.validate();expect(stopped.report.generations==2&&stopped.report.evaluations==120&&!stopped.report.converged&&std::string(stopped.report.status)=="output_function_stop","CMA clean generation stop preserves strict counts");Observer failure{PENTA_ITERATION_EVENT_GENERATION};failure.throwOnIter=true;observerException([&]{(void)module.solve(q,4,{}, {},std::ref(failure));});}
void roots(){Counter counter;double initial[]{0,0};penta_roots_request_v1 q{};q.struct_size=sizeof(q);q.operation=PENTA_ROOTS_SYSTEM;q.dimension=2;q.initial=initial;q.line_search=1;q.max_iterations=100;q.max_evaluations=1000;q.absolute_tolerance=1e-12;q.relative_tolerance=1e-12;q.residual_tolerance=1e-10;q.maximum_wall_seconds=30;q.callback_context=&counter;q.evaluate=rootResidual;penta::roots::Module module;const auto baseline=module.solve(q);const auto calls=counter.calls.load();counter.calls=0;Observer observer{PENTA_ITERATION_EVENT_EVALUATION};const auto observed=module.solve(q,{}, {},std::ref(observer));observer.validate();expect(baseline.solution==observed.solution&&counter.calls==calls,"KINSOL progress adds no evaluations or solution changes");Observer stop{PENTA_ITERATION_EVENT_EVALUATION,2};const auto stopped=module.solve(q,{}, {},std::ref(stop));stop.validate();expect(stopped.report.evaluations==2&&!stopped.report.converged&&std::string(stopped.report.status)=="output_function_stop","KINSOL supports clean evaluated-candidate stop");Observer failure{PENTA_ITERATION_EVENT_EVALUATION};failure.throwOnIter=true;observerException([&]{(void)module.solve(q,{}, {},std::ref(failure));});
    q.operation=PENTA_ROOTS_SCALAR;q.dimension=1;q.lower=-1;q.upper=3;q.initial=nullptr;counter.calls=0;const auto scalarBaseline=module.solve(q);const auto scalarCalls=counter.calls.load();std::vector<uint32_t> phases;counter.calls=0;const auto driver=std::this_thread::get_id();const auto scalarObserved=module.solve(q,{}, {},[&](const auto& s){expect(s.event==PENTA_ITERATION_EVENT_EVALUATION&&s.dimension==1&&std::this_thread::get_id()==driver,"TOMS748 reports owner-thread scalar evaluation snapshots");phases.push_back(s.phase);return false;});expect(scalarBaseline.solution==scalarObserved.solution&&counter.calls==scalarCalls,"TOMS748 progress adds no residual evaluations");expect(phases.front()==PENTA_ITERATION_INIT&&phases.back()==PENTA_ITERATION_DONE,"TOMS748 init/done phases");counter.calls=0;const auto scalarStop=module.solve(q,{}, {},[](const auto& s){return s.phase==PENTA_ITERATION_ITER&&s.evaluations>=2;});expect(counter.calls==2&&scalarStop.report.evaluations==2&&std::string(scalarStop.report.status)=="output_function_stop"&&!scalarStop.report.converged,"TOMS748 clean stop preserves last candidate without verification evaluation");
}
}
int main(){fit();optimize();evolve();roots();std::cout<<checks<<" native iteration checks, "<<failures<<" failures\n";return failures?1:0;}
